  "items:skytalon_recurve:name": "Arco recurvo garra del cielo",
  "items:slag_carapace:description": "Quitina endurecida y fundida con lava de una abominación de escoria. Material de calidad de herrería para piezas de armadura de la torre.",
  "items:slag_carapace:name": "Caparazón de escoria",
  "items:slagcarapace_plate:name": "Placa de caparazón de escoria",
  "items:slagforged_sword:name": "Espada forjada en escoria",
  "items:slagheart_cuirass:name": "Coraza de corazón de escoria",
  "items:slagweave_cape:name": "Capa de tejido de escoria",
  "items:slayer_amulet:description": "Un amuleto cristalino engastado con un fragmento del heraldo del vacío. Emana un poder frío y preciso en todos los estilos de combate.",
  "items:slayer_amulet:name": "Amuleto de cazador",
  "items:slayer_combat_draught:description": "Destilado de la esencia de la Torre del Cazador. Acelera tus golpes (-450ms de intervalo de ataque) y aguza tu puntería (+8% de crítico) durante 10 minutos.",
  "items:slayer_combat_draught:name": "Brebaje de combate del cazador",
  "items:slayer_greaves:description": "Grebas reforzadas con las esquirlas fracturadas de dientes de colmillo del pavor. Hechas para presas por encima de tu posición: +20 % de daño contra monstruos con un nivel de combate superior al tuyo.",
  "items:slayer_greaves:name": "Grebas de cazador",
  "items:slayer_helm:description": "Un yelmo magistral forjado con la esencia de los peores horrores de la Torre del Cazador. Marca la misión de su portador: +20 % de daño contra el objetivo actual de la tarea, y no se necesitan objetos de guarda contra ninguna amenaza de la torre mientras se lleva puesto.",
  "items:slayer_helm:name": "Yelmo de cazador",
  "items:slayer_hunters_cape:description": "Una capa desgastada que Brenna entrega a los cazadores que se han ganado sus primeros treinta contratos. El primer impacto de cada caza es el más contundente: +15 % de daño contra un objetivo ileso.",
  "items:slayer_hunters_cape:name": "Capa de cazador",
  "items:slayer_hunters_elixir:description": "Reservado para cazadores veteranos. Acelera tus ataques (-600ms de intervalo), +12% de crítico, +20% de daño crítico durante 30 minutos. Mejor duración sostenida que el Brebaje de combate.",
  "items:slayer_hunters_elixir:name": "Elixir de caza del cazador",
  "items:slayer_vambraces:description": "Avambrazos confeccionados con piel chamuscada de Desdichado de Brasas y cuero endurecido de la torre. Cada baja en la caza cierra las heridas del cazador: +4 de vida por baja.",
  "items:slayer_vambraces:name": "Avambrazos de cazador",
  "items:slayer_war_brew:description": "Una antigua fórmula de un maestro cazador. Acelera enormemente tus ataques (-750ms de intervalo), +20% de crítico, +30% de daño crítico durante 60 minutos. Reservado para las mayores cacerías.",
  "items:slayer_war_brew:name": "Poción de guerra del cazador",
  "items:slayer_ward_capsule:description": "Un recipiente sellado que contiene los cuatro componentes de guarda de la torre, fundidos en un único núcleo protector.",
  "items:slayer_ward_capsule:name": "Cápsula de guarda del cazador",
  "items:smokeweave_cape:name": "Capa de tejido de humo",
  "items:smugglers_key:name": "Llave del contrabandista",
  "items:sootscale_greaves:name": "Grebas de escama tiznada",
  "items:sorrow_staff:name": "Bastón de pena",
  "items:soul_amulet:name": "Amuleto de alma",
  "items:soul_flayer_fang:description": "Un colmillo curvo que apesta a almas quemadas. Botín raro del desollador de almas, codiciado como trofeo para el Muro de Trofeos del campamento.",
  "items:cinderwretch_hide:name": "Piel del Desdichado de Brasas",
  "items:cinderwretch_hide:description": "Una piel resistente, ennegrecida por un corazón de brasas eterno, arrancada a un Desdichado de Brasas en las profundidades de la torre. Componente de fabricación para los Avambrazos de cazador.",
  "items:soul_flayer_fang:name": "Colmillo del desollador de almas",
  "items:soul_veil:description": "Un sudario reluciente tejido con esencia de éter y runas del vacío. Repele los ataques de las criaturas incorpóreas.",
