  "quests:q_blackthorn_1:description": "Abate a 20 retoños que se sueltan de la maleza en el Bosque de Espino Negro: el bosque ha aprendido a defenderse.",
  "quests:q_blackthorn_1:name": "Adentrarse en el Bosque de Espino Negro",
  "quests:q_blackthorn_2:description": "Adéntrate más en el Bosque de Espino Negro, hacia los túmulos bajo sus raíces, y derrota a 25 retoños nudosos.",
  "quests:q_blackthorn_2:name": "La espesura nudosa",
  "quests:q_boar_hunter:description": "Mata a 15 jabalíes salvajes en Los Pastos: sin cercas ni pastor, han adoptado costumbres propias, y el Baluarte de las Brasas necesita sus pieles.",
  "quests:q_boar_hunter:name": "La cacería salvaje",
  "quests:q_crypt_1:description": "Entra en la Cripta y mata a 10 guerreros esqueleto: la Orden de los Guardianes de las Tumbas los selló hace tiempo; el sello ya no aguanta en todas partes.",
  "quests:q_crypt_1:name": "Huesos de los caídos",
  "quests:q_crypt_2:description": "Los salones inferiores de la Cripta están vigilados por lanceros esqueleto, una guarnición que ya no cobra sueldo. Abate a 20 de ellos.",
  "quests:q_crypt_2:name": "Muertos inquebrantables",
  "quests:q_crypt_3:description": "Los magos de hielo esqueleto rondan las bóvedas más profundas de la Cripta. Destruye a 10 antes de que te congelen por completo.",
  "quests:q_crypt_3:name": "Silencio helado",
  "quests:q_dire_wolf_hunt:description": "Los lobos terribles acechan en lo profundo del Bosque Salvaje: más grandes de lo que un lobo debería ser. Mata a 15 de estos feroces depredadores.",
  "quests:q_dire_wolf_hunt:name": "El terror de las tierras salvajes",
  "quests:q_fighter_1:description": "Derrota a 75 enemigos en total. La sangre y el sudor forjan al luchador que el Baluarte de las Brasas necesita.",
  "quests:q_fighter_1:name": "Luchador curtido",
  "quests:q_fighter_2:description": "Abate a 200 enemigos en total. Los Siervos ya empiezan a recordar tu nombre.",
  "quests:q_fighter_2:name": "Guerrero endurecido",
  "quests:q_fighter_3:description": "Derrota a 500 enemigos en total. Cada enemigo caído es una entrada que la ceniza nunca se queda.",
  "quests:q_fighter_3:name": "Veterano de cien batallas",
  "quests:q_first_blood:description": "Mata a 10 goblins en las Tierras Fronterizas: llevan demasiado tiempo saqueando las últimas granjas cerca del Baluarte de las Brasas.",
  "quests:q_first_blood:name": "Sangre de goblin",
  "quests:q_first_steps:description": "Caza 5 gallinas en Los Pastos, a las puertas del Baluarte de las Brasas: un primer manejo del arma, nada más.",
  "quests:q_first_steps:name": "Primeros pasos",
  "quests:q_frost_hound:description": "Los sabuesos de escarcha merodean por las Cavernas de Escarcha, donde el foso cavó demasiado hondo y encontró el frío del vacío. Caza a 15 de ellos.",
  "quests:q_frost_hound:name": "La cacería fría",
  "quests:q_gatherer:description": "Recoge 50 objetos de cualquier tipo para el Baluarte de las Brasas: tala madera, extrae mineral, recoge hierbas o saquea monstruos.",
  "quests:q_gatherer:name": "Recolector",
  "quests:q_gatherer_2:description": "Recolecta 5.000 objetos en total para el Baluarte de las Brasas. Esta tierra solo entrega lo poco que le queda a quienes perseveran.",
  "quests:q_gatherer_2:name": "Coleccionista implacable",
  "quests:q_goblin_slayer:description": "Rechaza aún más a la banda goblin: mata a 30 goblins en las Tierras Fronterizas, que antaño fueron el muro escudo del Confín.",
  "quests:q_goblin_slayer:name": "Cazador de goblins",
  "quests:q_miner_1:description": "Alcanza el nivel 5 de Minería y abre vetas más ricas para la forja del Baluarte de las Brasas.",
  "quests:q_miner_1:name": "Pico y piedra",
  "quests:q_miner_2:description": "Alcanza el nivel 30 de Minería. Las vetas más profundas de las Tierras Fronterizas exigen un brazo más fuerte.",
  "quests:q_miner_2:name": "Voluntad de hierro",
  "quests:q_miner_3:description": "Alcanza el nivel 50 de Minería. Los minerales más raros del Confín yacen muy por debajo de la superficie, más hondo que nunca.",
  "quests:q_miner_3:name": "La llamada de las profundidades",
  "quests:q_moss_golem_hunt:description": "Los gólems de musgo han invadido los claros del bosque: hasta el bosque necesita guardianes ahora. Destroza a 15 de ellos.",
  "quests:q_moss_golem_hunt:name": "Amenaza de musgo",
  "quests:q_roc_fledgling:description": "Los rocs polluelos dominan las corrientes térmicas de las Tierras Altas, donde el cielo aún corre limpio. Abate a 10 de estas colosales aves.",
  "quests:q_roc_fledgling:name": "Vigía de los cielos altos",
  "quests:q_shaman_hunt:description": "Los chamanes goblin sifonan Esencia Tenue de las viejas hogueras de guardia y agitan a la banda hacia la guerra. Silencia a 10 de ellos.",
  "quests:q_shaman_hunt:name": "Cacería de chamanes",
  "quests:q_skiller_1:description": "Alcanza un nivel total combinado de 20 en todas las habilidades: el Baluarte de las Brasas cuenta doble cada mano capaz.",
  "quests:q_skiller_1:name": "Aprendiz de todo",
  "quests:q_skiller_2:description": "Alcanza un nivel total combinado de 50. Quien solo domina un oficio no dura mucho en este mundo.",
  "quests:q_skiller_2:name": "Aventurero versátil",
  "quests:q_skiller_3:description": "Alcanza un nivel total combinado de 75. Muchos caminos te han traído hasta aquí, y el Baluarte de las Brasas no olvida ninguno.",
  "quests:q_skiller_3:name": "Aventurero curtido",
  "quests:q_skiller_4:description": "Alcanza un nivel total combinado de 100. Pocos de los que partieron del Baluarte de las Brasas han llegado tan lejos.",
  "quests:q_skiller_4:name": "Senda de la maestría",
  "quests:q_skiller_5:description": "Alcanza un nivel total combinado de 150. Tus hazañas se cuentan ahora junto al fuego del Baluarte de las Brasas, como antaño la leyenda de la Hearthforge, donde todos los oficios del Confín invernaron la caída del mundo.",
  "quests:q_skiller_5:name": "Leyenda de la Hearthforge",
  "quests:q_slagpit_1:description": "Aventúrate en el Foso de Escoria, donde antaño se fundía el hierro divino, y extermina 20 arañas del foso ocultas en las sombras.",
  "quests:q_slagpit_1:name": "Al fondo del foso",
  "quests:q_slagpit_2:description": "Los renacidos de hierro patrullan los pasadizos más profundos: herreros que murieron en su armadura y nunca recibieron la orden de detenerse. Abate a 10 de estos constructos imperecederos.",
  "quests:q_slagpit_2:name": "Acecho de hierro",
  "quests:q_smith_journeyman:description": "Alcanza el nivel 20 de Herrería. La forja del Baluarte de las Brasas premia la paciencia: domina lo básico antes de abordar metales más duros.",
  "quests:q_smith_journeyman:name": "Herrero oficial",
  "quests:q_smith_master:description": "Alcanza el nivel 50 de Herrería. Solo los verdaderamente entregados pueden trabajar los metales más raros del Confín: el hierro divino no perdona la impaciencia.",
  "quests:q_smith_master:name": "Maestro de la forja",
  "quests:q_stag_hunter:description": "Ciervos salvajes como monumentos dominan los Cotos de Caza del Bosque Salvaje. Abate a 20 de estas orgullosas bestias.",
  "quests:q_stag_hunter:name": "Rey del bosque",
  "quests:q_thorn_wolf_pack:description": "Los lobos espinosos del Bosque de Espino Negro son más peligrosos que los de su especie: el bosque los ha afilado. Mata a 20 de ellos.",
  "quests:q_thorn_wolf_pack:name": "Manada de lobos espinosos",
  "quests:q_wolf_slayer:description": "Caza 15 lobos grises en los Cotos de Caza del Bosque Salvaje: aquí todo ha crecido más, desde que nadie caza.",
  "quests:q_wolf_slayer:name": "Adentrarse en el Bosque Salvaje",
  "quests:q_woodcutter_1:description": "Alcanza el nivel 5 de Tala. Un hacha afilada y un corazón recio bastan: el Baluarte de las Brasas no pide más.",
  "quests:q_woodcutter_1:name": "Al bosque",
  "quests:q_woodcutter_2:description": "Alcanza el nivel 15 de Tala para cortar robles: el campamento necesita más que leña fina.",
  "quests:q_woodcutter_2:name": "Leñador curtido",
