  // ── New Haven / Encampment (0.3.0, Task #358): 15 Gebäude-Namen + Flavor ──
  "campBuildings:camp_townhall:name": "Casa Comunal",
  "campBuildings:camp_townhall:description": "Primero una choza con una mesa, luego una casa con campana: quien la oye sabe que en New Haven alguien está decidiendo.",
  "campBuildings:camp_watchtower:name": "Atalaya",
  "campBuildings:camp_watchtower:description": "Mientras alguien vigile arriba, el trabajo de abajo no descansa.",
  "campBuildings:camp_storehouse:name": "El Almacén",
  "campBuildings:camp_storehouse:description": "Alzado sobre pilotes de piedra, para que no entren ni la humedad ni las ratas. Voss envió el plano, junto con la orden de contarlo todo dos veces.",
  "campBuildings:camp_scrivener_tent:name": "La Tienda del Escribano",
  "campBuildings:camp_scrivener_tent:description": "Lo que se escribe de noche no hay que decidirlo por la mañana.",
  "campBuildings:camp_fishing_hut:name": "Cabaña del Pescador",
  "campBuildings:camp_fishing_hut:description": "El vado da más que paso, si sabes quedarte quieto el tiempo suficiente.",
  "campBuildings:camp_sawpit:name": "La Fosa de Aserrar",
  "campBuildings:camp_sawpit:description": "Un hombre arriba y otro abajo entre el serrín; de un modo u otro, salen vigas.",
  "campBuildings:camp_mine_adit:name": "La Bocamina",
  "campBuildings:camp_mine_adit:description": "La ladera no da nada gratis, pero da.",
  "campBuildings:camp_seed_garden:name": "El Jardín de Semillas",
  "campBuildings:camp_seed_garden:description": "Esta tierra lleva mucho sin dar nada bueno; se le está enseñando a confiar de nuevo.",
  "campBuildings:camp_fence_tent:name": "La Tienda del Perista",
  "campBuildings:camp_fence_tent:description": "Nadie pregunta de dónde viene la mercancía. Ese es el negocio.",
  "campBuildings:camp_workyard:name": "El Patio de Oficios",
  "campBuildings:camp_workyard:description": "Banco junto a banco bajo una lona: cada oficio trabaja más rápido cuando el vecino sujeta las tenazas.",
  "campBuildings:camp_smelter:name": "El Horno de Fundición",
  "campBuildings:camp_smelter:description": "El fuego no tiene horario: lo que entra vuelve a salir en lingotes, lo mires o no.",
  "campBuildings:camp_smokehouse:name": "El Ahumadero",
  "campBuildings:camp_smokehouse:description": "El humo es el cocinero más paciente del reino.",
  "campBuildings:camp_trophy_wall:name": "El Muro de Trofeos",
  "campBuildings:camp_trophy_wall:description": "Brenna paga por cabezas; el muro recuerda que fueron entregadas.",
  "campBuildings:camp_warden_shrine:name": "Santuario de los Silenciosos",
  "campBuildings:camp_warden_shrine:description": "Sin imagen, sin boca, sin mano: solo una piedra alzada y la posibilidad de que alguien escuche.",
  "campBuildings:camp_trade_post:name": "El Puesto Comercial",
  "campBuildings:camp_trade_post:description": "Mux manda el carro siempre que el camino lo permite; los precios son justos, dice Mux.",

