  "items:kestrel_loop:name": "Anillo del Cernícalo",
  "items:kestrel_loop:description": "Un aro delgado trabajado con la pluma primaria de un cernícalo, aún ligeramente aceitosa de la última cacería.",
  "items:hawkeye_gyre:name": "Banda del Ojo de Halcón",
  "items:hawkeye_gyre:description": "Engastada con una esquirla de rubí pulido, tallada como el ojo vigilante de un halcón. Calma la mano que tensa el arco.",
  "items:sinewbound_coil:name": "Anillo Ligado en Tendón",
  "items:sinewbound_coil:description": "Atado con tendón seco sobre una piedra ensangrentada. Quienes lo llevan afirman que zumba levemente antes de soltar la cuerda.",
  "items:windwidow_snare:name": "Sello de la Viuda del Viento",
  "items:windwidow_snare:description": "Nombrado por una cazadora que sobrevivió a cada blanco al que disparó una flecha. El diamante nunca refleja la luz del todo recto.",
  "items:blackfletch_nock:name": "Anillo de Pluma Negra",
  "items:blackfletch_nock:description": "Ónice engastado en piel de guerra, emplumado de negro para desvanecerse contra un cielo nocturno. La respuesta de los arqueros al anillo de ónice de los espadachines.",
  "items:ghostquiver_notch:name": "Banda del Carcaj Fantasma",
  "items:ghostquiver_notch:description": "Envuelta en piel de dragón vuelta pálida por los años. Quienes la llevan dicen que el carcaj a su espalda pesa menos, aunque nunca sea cierto.",
  "items:worldpiercer_barb:name": "Anillo del Perforamundos",
  "items:worldpiercer_barb:description": "Gema divina engastada en piel de sombra sobre un aro de aetherio. Se dice que atravesó con una flecha algo que no debería haber tenido un lado lejano.",
  "items:longsight_cord:name": "Cordón de Largavista",
  "items:longsight_cord:description": "Un cordón de cuero ensartado con esquirlas de zafiro. Lo llevan exploradores que aprendieron a confiar en sus ojos antes que en sus piernas.",
  "items:windwhisper_torc:name": "Torque del Susurro del Viento",
  "items:windwhisper_torc:description": "Un torque de cuero escamado engastado con rubí. Los jinetes juran que porta el sonido del vuelo de una flecha un latido antes de que impacte.",
  "items:harriers_clasp:name": "Cadena del Halcón Estrangulador",
  "items:harriers_clasp:description": "Cuero remachado ensartado con piedra de sangre, nombrado por un ave que nunca falla su segunda embestida.",
  "items:kitehunter_collar:name": "Colgante del Cazador de Milanos",
  "items:kitehunter_collar:description": "Diamante engastado en cuero remachado y alambre de mithril. Cuelga firme incluso a plena carrera.",
  "items:gloomfletch_choker:name": "Amuleto de Pluma Sombría",
  "items:gloomfletch_choker:description": "Ónice atrapado en piel de guerra oscura, emplumado con plumas que parecen beber la luz a su alrededor. La respuesta de los arqueros al amuleto de ónice.",
  "items:nightquarry_wreath:name": "Cadena de la Presa Nocturna",
  "items:nightquarry_wreath:description": "Piedra vacía enrollada en piel de dragón y hierro ennegrecido. Los trofeos cobrados a la luz de la luna nunca lucen igual de día.",
  "items:deadeye_reliquary:name": "Relicario del Ojo Certero",
  "items:deadeye_reliquary:description": "Un relicario de gema divina engastado en piel de sombra sobre aetherio. Guarda la última puntería de una arquera que nunca necesitó una segunda flecha.",

