  "items:emberglass_loop:name": "Anillo de Vidrio de Ascua",
  "items:emberglass_loop:description": "Un fragmento de fuego engastado tras un vidrio vuelto ámbar por un calor antiguo. Calienta la mano incluso antes de lanzar el hechizo.",
  "items:hollowlight_seal:name": "Sello de Luz Hueca",
  "items:hollowlight_seal:description": "Un fragmento de éter sellado en mithril, que brilla débilmente incluso a plena luz del día. El primer anillo del que un mago no debe avergonzarse.",
  "items:nightwell_loop:name": "Anillo del Pozo Nocturno",
  "items:nightwell_loop:description": "Ónice enroscado en torno a un fragmento del vacío, cuyo brillo procede de algo más oscuro que la luz de la luna. Nombrado por un pozo que ninguna antorcha ha iluminado jamás.",
  "items:voidscribe_glyph:name": "Brazalete del Escriba del Vacío",
  "items:voidscribe_glyph:description": "Una piedra del vacío grabada con un glifo que se reescribe solo cuando nadie mira. Quien lo lleva aprende a no leerlo con demasiada atención.",
  "items:godsight_loop:name": "Anillo de la Vista Divina",
  "items:godsight_loop:description": "Una gema divina engastada en plata bendita, que se dice muestra a su portador una verdad antes de cada hechizo. Pocos afirman disfrutar lo que ven.",
  "items:ashcant_cord:name": "Colgante del Cántico de Ceniza",
  "items:ashcant_cord:description": "Un rubí ensartado en alambre de hierro, envuelto con un cántico entonado sobre cenizas. Las palabras se olvidaron hace mucho; el calor permanece.",
  "items:gravecall_sigil:name": "Amuleto del Llamado de la Tumba",
  "items:gravecall_sigil:description": "Una piedra de sangre engastada en acero de tumba y esencia sepulcral, hecha para invocar un escudo desde un lugar que el hechicero no puede ver.",
  "items:duskveil_wreath:name": "Cadena del Velo del Ocaso",
  "items:duskveil_wreath:description": "Ónice envuelto en runita y tejido fantasma, que se dice oscurece un poco la sala allí donde se lleva.",
  "items:voidsong_locket:name": "Amuleto del Canto del Vacío",
  "items:voidsong_locket:description": "Un relicario de piedra del vacío que tararea una nota que nadie más puede oír. Los hechiceros juran que sigue el ritmo exacto de su propio pulso.",
  "items:godgem_reliquary:name": "Reliquiario de Gema Divina",
  "items:godgem_reliquary:description": "Un relicario de gema divina entretejido con tejido estelar, que guarda el último escudo de una hechicera que nunca necesitó un segundo.",

