  "items:gorecrown_locket:name": "Colgante de la Corona Sangrienta",
  "items:gorecrown_locket:description": "Una piedra de sangre engastada en acero de tumba sobre piel de guerra, que se dice recuerda cada batalla de la que su portador salió con vida.",
  "items:ironvow_collar:name": "Cadena del Juramento de Hierro",
  "items:ironvow_collar:description": "Un diamante ligado dos veces con alambre de mithril, llevado por guerreros que juraron un voto que pretenden sobrevivir.",
  "items:reavers_torc:name": "Torque del Saqueador",
  "items:reavers_torc:description": "Ónice engastado dos veces en runita, tomado de un saqueador que jamás dejó que un enemigo eligiera el terreno.",
  "items:bloodiron_locket:name": "Medallón de Hierro Sangriento",
  "items:bloodiron_locket:description": "Un medallón de piedra del vacío envuelto dos veces en hierro sangriento. No se abre a nada: la guerra que recuerda terminó mal para todos los demás.",
  "items:warcrown_reliquary:name": "Reliquiario de la Corona de Guerra",
  "items:warcrown_reliquary:description": "Un relicario de gema divina engastado dos veces en hierro divino, que guarda la corona de un señor de la guerra que jamás tuvo que alzarla en su defensa.",
  "items:cutthroat_loop:name": "Anillo del Degollador",
  "items:cutthroat_loop:description": "Un anillo de dientes de chacal, llevado por cazadores que esperan a que una herida se abra antes de atacar. Recompensa el golpe que acaba con todo.",
  "items:firstlight_seal:name": "Sello de la Primera Luz",
  "items:firstlight_seal:description": "Forjado de la primera brasa de un fuego de fragua. Cada combate se decide en el primer golpe, o no se decide en absoluto.",
  "items:tidewrack_collar:name": "Cadena de los Restos de Marea",
  "items:tidewrack_collar:description": "Cubierta de sal y fría, tomada de una cantora que ahogó marineros con su propia voz. Convierte la fuerza robada en un escudo.",
  "items:hollowmarch_notch:name": "Banda de la Marcha Hueca",
  "items:hollowmarch_notch:description": "Desgastada por una marcha interminable a través de salones vacíos. Se fortalece con cada paso que no se detiene.",
  "items:ashenvow_locket:name": "Colgante del Voto de Ceniza",
  "items:ashenvow_locket:description": "Un voto jurado sobre brasas ardientes, mantenido incluso cuando la llama se apagó. Golpea con más fuerza con el último aliento en los pulmones.",
  "items:rimeheart_locket:name": "Medallón de Corazón de Escarcha",
  "items:rimeheart_locket:description": "Congelado por completo por una maga de hielo que nunca sintió el frío. Castiga a todo lo que ya es demasiado lento para huir.",
  "items:thornwarden_seal:name": "Sello del Guardián de Espinas",
  "items:thornwarden_seal:description": "Tallado por un guardián que convertía cada golpe recibido en el siguiente que asestaba. Recompensa al luchador que sigue en pie.",
  "items:sunder_crown:name": "Corona Fragmentada",
  "items:sunder_crown:description": "Fragmento de una corona que no gobernó ningún reino único, llevada por quienes dominan todas las artes a la vez. Un golpe mortal impacta con más fuerza cuando podría haber venido de cualquier parte.",

  // ── Schmuck-Rework Welle 5 (29.08.2026): Skilling-Linie ─────────────────────────────────────
  "actions:craft_oreveined_hoop:name": "Fabricar anillo de vena de mineral",
  "actions:craft_thriftcut_cinch:name": "Fabricar anillo del corte ahorrativo",
  "actions:craft_steadhand_cuff:name": "Fabricar anillo de mano firme",
  "actions:craft_harvestward_clutch:name": "Forjar cadena de guarda de la cosecha",
  "items:oreveined_hoop:name": "Anillo de Vena de Mineral",
  "items:oreveined_hoop:description": "Engastado con una esquirla de zafiro sobre mineral en bruto, que aún huele levemente a la veta de la que se extrajo. Duplica el rendimiento de un golpe, de vez en cuando.",
  "items:thriftcut_cinch:name": "Anillo del Corte Ahorrativo",
  "items:thriftcut_cinch:description": "Un diamante engastado en mithril, pulido por manos que nunca desperdiciaron un solo corte de piel.",
  "items:steadhand_cuff:name": "Anillo de Mano Firme",
  "items:steadhand_cuff:description": "Ónice unido con alambre tocado por el vacío. Evita que la mano tiemble justo en el momento que más importa.",
  "items:harvestward_clutch:name": "Cadena de Guarda de la Cosecha",
  "items:harvestward_clutch:description": "Una cadena de piedra del vacío envuelta en tejido estelar, cálida como tierra recién removida incluso en pleno invierno.",
  "sets:hunters_accord_set:name": "Pacto del Cazador (2 piezas)",
