  "actions:brew_wardveil_tonic:name": "Preparar tónico de velo de guarda",
  "actions:brew_windstride_tonic:name": "Preparar tónico de zancada del viento",
  "items:duskfang_ripper:description": "Un puñal curvo forjado con la garra de un buitre: ligero, veloz y cruel al desenvainar.",
  "items:ribcage_hewer:description": "Un hacha de guerra de corteza de ent, con el filo templado en savia de Espino Negro hasta morder como el hierro.",
  "items:mossheart_crusher:description": "Un mazo de núcleo de gólem hecho de piedra y raíces compactas. Cada golpe cae como un muro derrumbado.",
  "items:chorus_impaler:description": "Una pica forjada en la tumba, con el asta envuelta en sudario. El silencio de la cripta cabalga en su punta.",
  "items:sentinel_coreblade:description": "Un mandoble forjado con el blindaje del núcleo de un centinela caído. Zumba débilmente con la carga de guarda que le queda.",
  "items:colossus_marrowaxe:description": "Una colosal hoja de hacha tallada en hueso de médula petrificado. Parte hacia lo más grande de la sala.",
  "items:wisp_kindled_bough:description": "Una rama de madera de ciénaga que aún humea con fuego fatuo atrapado en su punta nudosa.",
  "items:chitinshell_sparker:description": "Una varita con núcleo de quitina de escarabajo, que chisporrotea con estática en cada golpe.",
  "items:barrowsong_crook:description": "Un cetro funerario arrebatado a un cantor de túmulos, aún frío al tacto.",
  "items:briarbound_conduit:description": "Un orbe catalizador atado con zarza viva, que zumba con el oficio sobrante de la bruja.",
  "items:choirbound_relic:description": "Un bastón rescatado del santuario del coro hueco. Lleva su zumbido a cada golpe.",
  "items:voidherald_flightbow:description": "Un arco largo encordado con tendón tocado por el vacío, sacado del relicario del propio heraldo.",
  "items:soulflayer_snapbow:description": "Un arco recurvo corto y retorcido, tallado en cuerno de almas desolladas. Su tensado es casi silencioso.",
  "items:voidhusk_deadeye:description": "Un pesado arco largo revestido con la cáscara de un vaciocáscara, hecho para un solo disparo mortal a la vez.",
